import { Group, Mesh, PlaneGeometry } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { orbit, depthRotate, dissolveMorph, displacementTransition, parallaxScroll, magneticCursor, particleEmerge, flyThrough, kineticText } from '@/primitives';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // ---------- Textured Plane ----------
  const imgUrl = config.imageUrl;
  const geometry = new ctx.THREE.PlaneGeometry(1, 320 / 512);
  const material = new ctx.THREE.MeshBasicNodeMaterial();
  const mesh = new ctx.THREE.Mesh(geometry, material);
  group.add(mesh);

  // Load texture asynchronously
  let texResource = null;
  ctx.textureLoader
    .loadTexture(imgUrl)
    .then((tex) => {
      texResource = tex;
      material.mapNode = texture(tex);
    })
    .catch(() => {
      // texture texture
    });

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textObjects = [];

  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 0.34,
      color: (config.intent?.visualSpec?.colors?.paper) || '#e8ecf2',
      align: 'center',
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    // Position text slightly above the plane
    txt.position.set(0, 0, 0.01);
    group.add(txt);
    textObjects.push(txt);
  }

  // ---------- Handlers ----------
  group.userData.handlers = {};

  // ---------- Cleanup ----------
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texResource) texResource.dispose();
    for (const txt of textObjects) {
      if (txt.parent) txt.parent.remove(txt);
    }
    // No GSAP timelines in this node, but kill any if present
    if (group.userData._gsapTimelines) {
      for (const tl of group.userData._gsapTimelines) tl.kill();
    }
  };

  return group;
}
